// ---- foam claw: row of shrinking foam blobs along a curling arc ----
function foamClaw(len, r0, n){
  const g = new THREE.Group();
  for (let i=0;i<n;i++){
    const t = i/(n-1);
    const s = new THREE.Mesh(new THREE.IcosahedronGeometry(r0*(1-t*0.55), 0), flat(C.foam));
    s.position.set(-len/2 + t*len, Math.sin(t*Math.PI*0.9)*r0*1.7, -t*len*0.2);
    s.scale.y = 0.85;
    g.add(s);
  }
  return g;
}

// ---- wave: solid curling mass = big base + rising curl of fat discs (overlapping, no gaps) ----
function makeWave({w=10, h=7, color=C.waveMid, curl=0.5, foam=true}={}){
  const g = new THREE.Group();
  // solid base mound
  const base = new THREE.Mesh(new THREE.CylinderGeometry(w*0.55, w*0.7, h*0.55, 9), flat(color));
  base.position.y = h*0.27;
  g.add(base);
  // rising curl: overlapping fat discs, each lower than the gap so no plate look
  const n = 8;
  for (let i=0;i<n;i++){
    const t = i/(n-1);
    const r = w*0.5*(1 - t*0.55);
    const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 1.4, 9), flat(color));
    m.position.y = h*0.45 + t*h*0.6;
    m.position.z = -t*t*h*curl;
    g.add(m);
  }
  if (foam){
    const claw = foamClaw(w*0.85, w*0.13, 12);
    claw.position.y = h*1.02;
    claw.position.z = -h*curl*0.7;
    g.add(claw);
  }
  return g;
}

